/// One item: the shared envelope (id, source, kind, title, updatedAt; createdAt, deepLink, body and raw when there are) plus the fields of its kind.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum Item {
    Event(EventItem),
    Message(MessageItem),
    Task(TaskItem),
    Note(NoteItem),
    File(FileItem),
    Person(PersonItem),
    Entry(EntryItem),
    Metric(MetricItem),
    Record(RecordItem),
}

/// The item's id, unique within its source and kept as the source gives it. An index keys items by source.connector, source.instance and id; there is no global id format.
pub type ItemId = String;

/// Where the item came from: the connector plugin and its instance.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ItemSource {
    pub connector: PluginId,
    pub instance: InstanceId,
}

/// One connection of a connector, unique within it: default, work, personal.
pub type InstanceId = String;

/// An RFC 3339 time with an offset (Z or +09:00); a time without one is refused.
pub type Timestamp = String;

/// One line that names the item in a list.
pub type ItemTitle = String;

/// The item's text (a note's content, a message's body), as Markdown or plain text.
pub type ItemBody = String;

/// A URL that opens the item in its own app: https:, or the app's scheme (message:, x-apple-reminder:). It is the way back to the original.
pub type DeepLink = String;

/// Everything else the source said about the item, as it said it. Views may read it (raw.labels); nothing else depends on its shape.
pub type ItemRaw = serde_json::Map<String, serde_json::Value>;

/// A person an item names, by name, email or both.
